import React, { useState, useEffect } from "react";

const FALLBACK_VIDEOS = [
	{
		id: { videoId: "6_pGleUf4aU" },
		snippet: {
			title: "Introducing iPhone 16 Pro | Apple",
			description:
				"Meet iPhone 16 Pro and iPhone 16 Pro Max. Built for Apple Intelligence. Featuring Camera Control, 4K 120 fps Dolby Vision.",
			thumbnails: {
				high: { url: "https://i.ytimg.com/vi/6_pGleUf4aU/hqdefault.jpg" },
			},
		},
	},
	{
		id: { videoId: "0x8x6sYJkF4" },
		snippet: {
			title: "The all-new iPad Pro | Thinpossible | Apple",
			description:
				"Introducing the ridiculously thin iPad Pro. Powered by the breakthrough Apple M4 chip with Ultra Retina XDR display.",
			thumbnails: {
				high: { url: "https://i.ytimg.com/vi/0x8x6sYJkF4/hqdefault.jpg" },
			},
		},
	},
	{
		id: { videoId: "OG7rF5rBf5E" },
		snippet: {
			title: "Introducing Apple Watch Series 10 | Apple",
			description:
				"Our thinnest watch ever. Featuring our biggest display, sleep tracking insights, and faster charging.",
			thumbnails: {
				high: { url: "https://i.ytimg.com/vi/OG7rF5rBf5E/hqdefault.jpg" },
			},
		},
	},
	{
		id: { videoId: "Vb0UQbWk9z0" },
		snippet: {
			title: "MacBook Air | Lean. Mean. M3 machine | Apple",
			description:
				"The world's most popular laptop is better than ever with the M3 chip and up to 18 hours of battery life.",
			thumbnails: {
				high: { url: "https://i.ytimg.com/vi/Vb0UQbWk9z0/hqdefault.jpg" },
			},
		},
	},
	{
		id: { videoId: "eDqfg_LexCQ" },
		snippet: {
			title: "AirPods 4 & AirPods Pro 2 | Sound Reimagined | Apple",
			description:
				"Discover the iconic sound of AirPods with active noise cancellation and personalized spatial audio.",
			thumbnails: {
				high: { url: "https://i.ytimg.com/vi/eDqfg_LexCQ/hqdefault.jpg" },
			},
		},
	},
	{
		id: { videoId: "X8kHqfXyqLg" },
		snippet: {
			title: "Apple TV 4K & Apple Originals | Apple",
			description:
				"Experience critically acclaimed movies and series with 4K Dolby Vision and Dolby Atmos sound.",
			thumbnails: {
				high: { url: "https://i.ytimg.com/vi/X8kHqfXyqLg/hqdefault.jpg" },
			},
		},
	},
];

function YoutubeAPI() {
	const [youtubeData, setYoutubeData] = useState([]);
	const [loading, setLoading] = useState(true);

	const API_KEY =
		process.env.REACT_APP_YOUTUBE_API_KEY ||
		"AIzaSyCpTF_yLNSD38RsC4Q8fszQZCJNZ6F8Kvc";
	const CHANNEL_ID =
		process.env.REACT_APP_YOUTUBE_CHANNEL_ID || "UCYFQ33UIPERYx8-ZHucZbDA";
	const MAX_RESULTS = 6;

	useEffect(() => {
		const fetchVideos = async () => {
			try {
				const res = await fetch(
					`https://www.googleapis.com/youtube/v3/search?key=${API_KEY}&channelId=${CHANNEL_ID}&part=snippet,id&order=date&maxResults=${MAX_RESULTS}`,
				);
				const data = await res.json();
				if (data.items && data.items.length > 0) {
					setYoutubeData(data.items);
				} else {
					console.warn("YouTube API returned no items, using fallback", data);
					setYoutubeData(FALLBACK_VIDEOS);
				}
			} catch (error) {
				console.error("Error fetching YouTube data, using fallback:", error);
				setYoutubeData(FALLBACK_VIDEOS);
			} finally {
				setLoading(false);
			}
		};

		fetchVideos();
	}, [API_KEY, CHANNEL_ID]);


	return (
		<div className="allVideosWrapper pb-5">
			<div className="container">
				<div className="row justify-content-center text-center">
					<div className="col-12 mt-5 mb-4">
						<div className="title-wrapper bold" style={{ fontSize: "36px", fontWeight: "700" }}>
							Latest Videos
						</div>
					</div>

					{loading && <div className="col-12 text-center py-4">Loading videos...</div>}

					{youtubeData?.map((singleVideo, i) => {
						const vidId = singleVideo.id?.videoId;
						const snippet = singleVideo.snippet;
						if (!vidId || !snippet) return null;

						const videoLink = `https://www.youtube.com/watch?v=${vidId}`;
						const thumbUrl =
							snippet.thumbnails?.high?.url ||
							snippet.thumbnails?.medium?.url ||
							snippet.thumbnails?.default?.url;

						return (
							<div key={vidId || i} className="col-sm-12 col-md-6 col-lg-4 mb-4 text-start">
								<div className="singleVideoWrapper h-100 p-2 d-flex flex-column">
									<div className="videoThumbnail mb-2">
										<a href={videoLink} target="_blank" rel="noopener noreferrer">
											<img
												src={thumbUrl}
												alt={snippet.title}
												className="img-fluid rounded shadow-sm w-100"
												style={{ objectFit: "cover", height: "200px" }}
											/>
										</a>
									</div>
									<div className="videoInfo mt-2">
										<div className="videoTitle mb-2">
											<a
												href={videoLink}
												target="_blank"
												rel="noopener noreferrer"
												style={{
													color: "#0071e3",
													textDecoration: "none",
													fontSize: "14px",
													fontWeight: "600",
													lineHeight: "1.4",
													display: "-webkit-box",
													WebkitLineClamp: 2,
													WebkitBoxOrient: "vertical",
													overflow: "hidden",
												}}
											>
												{snippet.title}
											</a>
										</div>
										<div
											className="videoDesc text-secondary"
											style={{
												fontSize: "13px",
												lineHeight: "1.4",
												display: "-webkit-box",
												WebkitLineClamp: 3,
												WebkitBoxOrient: "vertical",
												overflow: "hidden",
											}}
										>
											{snippet.description}
										</div>
									</div>
								</div>
							</div>
						);
					})}
				</div>
			</div>
		</div>
	);
}

export default YoutubeAPI;
